const templateManager = new (require("./editJournal-templates.coffee"));

class JournalCommentsCtrl {
	constructor(cmId, assignId, studentId) {
		this.cmId = cmId;
		this.assignId = assignId;
		this.studentId = studentId;
	}

	setComment(comment) {

		let template = Handlebars.compile(templateManager.setCommentTpl);

		const saveDeffered = $.Deferred();

		const setComment = (commentText) => {
			const queryData = {
				studentId: this.studentId,
				cmId: this.cmId,
				assignId: this.assignId
			}

			let saveData = null;
			if (commentText) {
				saveData = "=" + commentText;
			}

			return jsSubmit({
				data: saveData,
				queryData: queryData,
				action: "/webapi/grade/journal/comments",
				method: "POST",
				nocache: true,
				showProcessing: true
			});
		}

		const saveHandler = (dialog) => {
			let commentTextArea = $("textarea[name=comment]", dialog.$modalContent).get(0);
			let commentText = commentTextArea.value.trim();

			if (commentText) {
				setComment(encodeURIComponent(commentText))
					.then(() => {
						dialog.successClose();
						saveDeffered.resolve(commentText);
					});
			}
			else {
				commentTextArea.value = "";
				alert(language.Generic.Common.kEnterComment);
			}
		}

		$.show.dialog({
			title: comment ? language.Generic.Common.kEditComment : language.Generic.Common.kAddComment,
			message: template({
				language: language
			}),
			onshow: (dialog) => {
				let commentTextArea = $("textarea[name=comment]", dialog.$modalContent).get(0);

				if (comment) {
					commentTextArea.value = comment;
				}
			},
			onshown: (dialog) => {
				$("textarea[name=comment]", dialog.$modalContent).focus();
				$("textarea[name=comment]").keydown(function (e) {
					if (e.keyCode === 13 && e.shiftKey) {
						saveHandler(dialog);
					}
				});
			},
			size: BootstrapDialog.SIZE_WIDE,
			buttons: [
				{
					label: comment ? language.Generic.Buttons.kSave : language.Generic.Buttons.kAdd,
					action: saveHandler,
					cssClass: "btn-primary"
				},
				{
					label: language.Generic.Buttons.kRemove,
					action: function (dialog) {
						$.show.confirmation(language.Generic.Common.kMsgAreYouSure).then(() => {
							setComment(null)
								.then(() => {
									dialog.successClose();
									saveDeffered.resolve(null);
								});
						});

					}
				},
				{
					label: language.Generic.Buttons.kCancel,
					hotkey: 23,
					action: function (dialog) {
						return dialog.close();
					}
				}
			]
		});

		

		return saveDeffered.promise();
	}
}


module.exports = JournalCommentsCtrl;


