const gradeConstants = require("./journal-constants.js");
const templateManager = new (require("./editJournal-templates.coffee"));
const resourceLoader = require("./resourceLoader.coffee");
const homeAssignSelectorCtrl = require("./planHomeAssignSelector.js").HomeAssignSelectorCtrl;

class CreateAssignCtrl {
	constructor(ctx, lessonId, classMeetings, settings, extraDataProvider) {
		this.ctx = ctx;
		this.sgId = ctx.subjectGroupId;
		this.cmId = ctx.classMeetingId;

		this.settings = settings;
		this.classMeetings = classMeetings;
		this.extraDataProvider = extraDataProvider;
	}

	//добавление задания
	addAssign() {
		const defaultAssignName = this.settings.subjectPlan.lesson ? this.settings.subjectPlan.lesson.lessonName : language.Generic.Grade.kNoTheme;

		const model = {
			assignmentName: defaultAssignName,
			assignmentTypes: null,
			assignmentTypesChoise: true,
			typeId: null,
			language: language,
			variants: null
		};

		let types = _.filter(this.settings.refs.assignmentTypes, (type) => type.id !== gradeConstants.assignmentTypes.homeWork);

		if (!this.settings.moduleQA) {
			types = _.filter(types, (type) => type.id !== gradeConstants.assignmentTypes.DKR);
			model.typeId = this.settings.lessonAnswerTypeId;
		} else {
			model.variants = [];
		}
		model.assignmentTypes = types;

		return this._createAssign(model, templateManager.addAssignTpl);
	}

	//добавление домашнего задания
	addHomeAssign() {
		const ctrl = this;

		const prevCms = _.chain(this.classMeetings)
			.filter((cm) => cm.date < this.ctx.classMeetingDay)
			.sortBy((cm) => cm.date)
			.value()
			.reverse();

		if (!prevCms.length) {
			prevCms.push(_.findWhere(this.classMeetings, { id: this.cmId }));
		}

		let lessons;
		const lessonsReady = resourceLoader.getSubjectPlan({ sgId: this.sgId }).then((sp) => {
			lessons = sp.lessons;

			_.each(prevCms, (cm) => {
				cm.displayName = cm.name;
				const lessonInfo = _.findWhere(lessons, { id: cm.lessonId });
				if (lessonInfo) {
					cm.displayName += " - " + lessonInfo.displayName;
				}
			});
		});

		const types = _.filter(this.settings.refs.assignmentTypes, (type) => type.id === gradeConstants.assignmentTypes.homeWork);

		const model = {
			assignmentName: "",
			assignmentTypes: types,
			assignmentTypesChoise: false,
			fromKTP: !this.settings.subjectPlan.noSubjectPlan,
			typeId: gradeConstants.assignmentTypes.homeWork,
			language: language,
			prevClassmeetings: prevCms
		};

		const onShowEventHandler = (dialog) => {
			const prevCmSelect = $("select[name=ISSUECMID]", dialog.$modalContent);
			const homeAssignNameInput = $("input[name='AN']", dialog.$modalContent);
			const usePlanBtn = $("#useLessonHomeAssignBtn", dialog.$modalContent);

			let lessons;
			resourceLoader.getSubjectPlan({ sgId: this.sgId }).then((sp) => {
				lessons = sp.lessons;
			});

			let prevCmId;
			let prevCmInfo;

			prevCmSelect.change(() => {
				prevCmId = parseInt(prevCmSelect.val());
				prevCmInfo = _.findWhere(this.classMeetings, { id: prevCmId });
			});

			if (prevCms.length) {
				prevCmSelect.val(prevCms[0].id);
			}
			prevCmSelect.trigger("change");

			usePlanBtn.click(() => {
				const getHomeAssignCtrl = new homeAssignSelectorCtrl(this.sgId);
				getHomeAssignCtrl.execute(ctrl.cmId, prevCmInfo).then((result) => {
					homeAssignNameInput.val(result.lessonInfo.homeAssign || result.lessonInfo.lessonName);
				});
			});
		};

		return lessonsReady.then(() => {
			return ctrl._createAssign(model, templateManager.addHomeAssignTpl, { onShown: onShowEventHandler });
		});
	}

	//добавление домашнего задания на будущие даты
	addNextHomeAssign() {
		var ctrl = this;
		jsSubmit({
			action: "/asp/ajax/classmeetings/getnextclassmeetingsforsg.asp",
			data: {
				sgid: this.sgId,
				cmid: this.cmId
			},
			showProcessing: true
		}).then((response) => {
			var nextClassMeetings = response.data.nextClassMeetings;

			if (nextClassMeetings.length === 0) {
				$.show.message(language.Generic.Grade.kNoNextClassmeetings);
				return;
			}
			if (this.settings.editLimit.limitPastEditHomeAssigns) {
				var now = new Date();
				nextClassMeetings = _.filter(nextClassMeetings, (cm) => new Date(cm.day) > now);
				if (nextClassMeetings.length === 0) {
					$.show.message(language.Generic.Grade.kCantAssignToPastClassmeetings);
					return;
				}
			}

			var model = {
				assignmentTypes: _.filter(this.settings.refs.assignmentTypes, (type) => type.id === gradeConstants.assignmentTypes.homeWork),
				assignmentTypesChoise: false,
				issueCmId: this.cmId,
				typeId: gradeConstants.assignmentTypes.homeWork,
				language: language,
				fromKTP: !this.settings.subjectPlan.noSubjectPlan,
				classMeetings: nextClassMeetings
			};

			if (this.settings.subjectPlan.lesson) {
				model.lesson = this.settings.subjectPlan.lesson;
				resourceLoader.getSubjectPlan({ sgId: this.sgId }).then((sp) => {
					model.lesson = _.findWhere(sp.lessons, { id: model.lesson.id });
				});
			}

			var template = Handlebars.compile(templateManager.addNextHomeAssignTpl);
			var html = template(model);

			const issueCmInfo = _.findWhere(ctrl.classMeetings, { id: this.cmId });
			let nextCmCombo = null;
			let assignNameInput = null;
			let nextCmInfo = null;
			let nextCmId = null;

			$.show.dialog({
				title: language.Generic.Grade.kAddHomeAssignOnNextClassmeeting,
				message: html,
				size: BootstrapDialog.SIZE_WIDE,
				buttons: [
					{
						label: language.Generic.Buttons.kAdd + "/" + language.Generic.Buttons.kEdit,
						action: (dialog) => {
							if (!this._validate(null, assignNameInput)) {
								return;
							}

							let homeAssignId = 0;
							if (nextCmInfo && nextCmInfo.homeAssignment) {
								homeAssignId = nextCmInfo.homeAssignment.id || 0;
							}

							const name = assignNameInput.val();

							jsSubmit({
								data: {
									cmid: nextCmId,
									sgid: this.sgId,
									issuecmid: this.cmId,
									assignmentId: homeAssignId,
									an: name
								},
								action: "/asp/ajax/Assignments/CreateOrEditHomeAssignment.asp",
								nocache: true,
								showSuccessMessage: true
							})
							.then(() => dialog.successClose());
						},
						hotkey: 13,
						cssClass: 'btn-primary'
					},
					{
						label: language.Generic.Buttons.kCancel,
						hotkey: 23,
						action: function (dialog) {
							return dialog.close();
						}
					}
				],
				onshow: (dialog) => {
					nextCmCombo = $('select[name=NEXTCMID]', dialog.$modalContent);
					assignNameInput = $('input[name=AN]', dialog.$modalContent);

					$("#useLessonHomeAssignBtn", dialog.$modalContent).click(() => {
						const getHomeAssignCtrl = new homeAssignSelectorCtrl(this.sgId);
						getHomeAssignCtrl.execute(nextCmId, issueCmInfo).then(function (result) {
							assignNameInput.val(result.lessonInfo.homeAssign || result.lessonInfo.lessonName);
							result.dialog.close();
						});
					});

					const syncNextCmHomeAssign = () => {
						nextCmId = parseInt(nextCmCombo.val());
						nextCmInfo = _.findWhere(model.classMeetings, { id: nextCmId });
						if (nextCmInfo && nextCmInfo.homeAssignment) {
							assignNameInput.val(nextCmInfo.homeAssignment.name || "");
						} else {
							assignNameInput.val("");
						}
					};
					syncNextCmHomeAssign();
					nextCmCombo.change(syncNextCmHomeAssign);
				}
			});
		});
	}

	//метод базовой валидации формы создания заданий
	_validate(typeSelect, nameInput) {
		var typeId;
		if (typeSelect) {
			typeId = typeSelect.val();
			if (typeId <= 0) {
				alert(language.Generic.Assignment.kATPleaseSelectAssignmentType);
				typeSelect.focus();
				return false;
			}
		}
		var name = nameInput.val();
		if (trimStr(name).length === 0) {
			alert(language.Generic.Assignment.kATEnterAssignmentTheme);
			nameInput.focus();
			return false;
		}
		if (trimStr(name).length > gradeConstants.maxLengths.assignTitle) {
			alert(language.Generic.Assignment.kATAssignmentThemeNotMayBe);
			nameInput.focus();
			return false;
		}
		return true;
	}

	//базовый метод создания заданий
	_createAssign(model, template, options) {
		const defOptions = {
			//обработчик события показ модального окна
			onShow: null,
			//возможность расширения валидации
			check: null
		}

		options = $.extend({}, defOptions, options);

		const templateCompiled = Handlebars.compile(template);

		const saveDeffered = $.Deferred();

		$.show.dialog({
			title: language.Generic.Grade.kCreateAssignment,
			message: templateCompiled(model),
			size: BootstrapDialog.SIZE_WIDE,
			buttons: [
				{
					label: language.Generic.Buttons.kAdd,
					hotkey: 13,
					action: (dialog) => {
						const typeSelect = $("select,input", dialog.$modalContent).filter("[name=AType]");
						const nameInput = $("input[name=AN]", dialog.$modalContent);

						if (!this._validate(typeSelect, nameInput)) {
							return;
						}

						let typeId = parseInt(typeSelect.val() || -1);
						if (typeId === -1) {
							$.show.message(language.Generic.Assignment.kATPleaseSelectAssignmentType);
							return;
						}

						const typeInfo = this.settings.refs.assignmentTypesIndex[typeId];
						const name = nameInput.val();

						let dwVariantId = null;
						let dwTestPlanId = null;

						if (this.settings.moduleQA && typeInfo.id === gradeConstants.assignmentTypes.DKR) {
							let diagnosticWorkData = $("*[name=DiagnosticWork]", dialog.$modalContent).val();
							if (!diagnosticWorkData) {
								alert(language.Generic.Assignment.kChooseDiagnosticWorkVariant);
								nameInput.focus();
								return false;
							}
							diagnosticWorkData = diagnosticWorkData.split("_");
							dwVariantId = diagnosticWorkData[0];
							dwTestPlanId = diagnosticWorkData[1];
						}

						if (options.check && !options.check()) {
							return;
						}

						let lessonId = this.settings.subjectPlan.lesson ? this.settings.subjectPlan.lesson.id : -1;

						let saveData = {
							sgid: this.sgId,
							cmid: this.cmId,
							lessonId: lessonId,
							RegimeAddAssign: 1,
							AN: name,
							AType: typeId,
							saveJournal: 0//this.performanceChanged ? 1 : 0
						};

						if (typeInfo.id === gradeConstants.assignmentTypes.DKR) {
							saveData.dwVariantId = dwVariantId;
							saveData.dwTestPlanId = dwTestPlanId;
						}

						if (typeInfo.id === gradeConstants.assignmentTypes.homeWork) {
							saveData.issueCmId = $("select[name=ISSUECMID]").val();
						}

						if (this.extraDataProvider) {
							const extraData = this.extraDataProvider();
							saveData = $.extend(saveData, extraData);
						}

						jsSubmit({
							data: saveData,
							action: "/webapi/grade/journal/edit",
							method: "POST",
							nocache: true,
							showProcessing: true
						}).then((response) => {

							window.dataWereChanged = false;

							let newAssign = {
								id: response.assignmentId,
								name: response.assignmentName,
								typeId: typeId,
								typeName: typeInfo.id === gradeConstants.assignmentTypes.DKR ? typeInfo.abbr : typeInfo.name,
							};

							dialog.successClose();

							if (this.settings.moduleQA && _.contains(gradeConstants.testPlansTypes, newAssign.typeId)) {
								const templateMessageAdd = Handlebars.compile(templateManager.messageAssignmentAdded);
								const modelMessage = {
									assignId: newAssign.id,
									isTestPlansType: _.contains(gradeConstants.testPlansTypes, newAssign.typeId),
									language: language
								};
								$.show.message(templateMessageAdd(modelMessage));
							}

							saveDeffered.resolve(newAssign);
						});
					},
					cssClass: "btn-primary"
				},
				{
					label: language.Generic.Curriculum.kBtnCancel,
					hotkey: 23,
					action: function (dialog) {
						return dialog.close();
					}
				}
			],
			onshow: function (dialog) {
				if (options.onShow) {
					return options.onShow(dialog);
				}
			},
			onshown: function (dialog) {
				if (options.onShown) {
					return options.onShown(dialog);
				}
			}

		});

		return saveDeffered.promise();
	}
}


module.exports = CreateAssignCtrl;


